/*
 * prog16_word_count_fsm – reproduced behavior
 *
 * The original binary implements a tiny “wc”‑like utility.
 * It reads stdin character‑by‑character, counts:
 *   • LINES – the number of '\n' characters,
 *   • WORDS – the number of whitespace‑separated words,
 *   • CHARS – the total number of bytes read (excluding EOF).
 *
 * After reaching EOF it prints the three counters in the exact
 * format used by the original program:
 *
 *     LINES=%ld WORDS=%ld CHARS=%ld\n
 *
 * The implementation below follows the same semantics but is
 * written in clear, idiomatic C.
 */

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    long lines = 0;   /* number of newline characters */
    long words = 0;   /* number of words */
    long chars = 0;   /* total characters read */

    int c;
    int in_word = 0;  /* flag: currently inside a word */

    while ((c = getc(stdin)) != EOF) {
        ++chars;

        if (c == '\n')
            ++lines;

        if (isspace((unsigned char)c)) {
            /* leaving a word (if we were in one) */
            in_word = 0;
        } else {
            /* entering a word */
            if (!in_word) {
                ++words;
                in_word = 1;
            }
        }
    }

    printf("LINES=%ld WORDS=%ld CHARS=%ld\n", lines, words, chars);
    return 0;
}
